// Point-in-time recovery: replay the write-ahead log up to a target timestamp
const wal=[{ts:100,op:'set',k:'a',v:1},{ts:200,op:'set',k:'a',v:2},{ts:300,op:'del',k:'a'},{ts:400,op:'set',k:'b',v:9}];
const target=150;
const state={};
for(const e of wal){if(e.ts>target)break;if(e.op==='set')state[e.k]=e.v;else delete state[e.k];}
console.log('state at ts='+target+':',JSON.stringify(state));

